import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.Cq50P25D.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"usage/security.md","filePath":"en/usage/security.md","lastUpdated":1785650278000}`),a={name:`usage/security.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><p>Sync Engine handles your vault files, remote storage credentials, and executable modules. This page explains what it trusts, what it cannot protect, and what you can do to reduce risk.</p><h2 id="trust-boundary" tabindex="-1">Trust Boundary <a class="header-anchor" href="#trust-boundary" aria-label="Permalink to “Trust Boundary”">​</a></h2><p>Sync Engine trusts the local operating system, Obsidian, and the device where it runs. Anyone or any software that can control your device or Obsidian session may also be able to access your vault and configured credentials. Sync Engine cannot protect against a compromised device.</p><p>Sync Engine also assumes users are rational about your own security, and allows everything if the user explicitly approves.</p><p>Modules are executable code. An enabled module can receive broad Obsidian and Sync Engine access, including vault files and network requests. This is required by the extensible design, but it means you should treat modules like plugins and only enable ones you trust.</p><p>Without client-side encryption, the configured backend receives the files you sync. The backend and network should therefore be treated as places where your data may be exposed or changed. The <a href="./../deep-dive/modules/encryption">Encryption module</a> lets the client encrypt file contents and names before upload. It does not hide every detail: the backend can still learn information such as file sizes, modification times, and the number of files, and it may still delete or roll back remote data.</p><h2 id="what-sync-engine-does" tabindex="-1">What Sync Engine Does <a class="header-anchor" href="#what-sync-engine-does" aria-label="Permalink to “What Sync Engine Does”">​</a></h2><ul><li>Only configured backends and module sources receive requests. Sync Engine has no telemetry. See <a href="./permissions">Permissions</a> for request timing and scope.</li><li>New modules are disabled by default. Sync Engine records your approval separately from the module file and checks the module&#39;s integrity before loading it, unless you explicitly turn that check off. See <a href="./../deep-dive/extensibility">extensibility contract</a> for the exact boundaries.</li><li>Automatic updates only apply to an already installed module from the same source. A newly discovered module without any download record triggers an explicit warning of potential malice.</li><li>Official modules only read secrets that their documented function requires. Secrets are stored through Obsidian&#39;s secret storage rather than in ordinary settings.</li><li>Every official module are reviewed by accountable real human maintainers before they are entitled &quot;official&quot;.</li></ul><p>These safeguards reduce accidental or unauthorized module execution. They do not make an untrusted module safe after you approve and enable it. Source links and integrity checks are useful evidence, not a substitute for judgment.</p><h2 id="improve-your-security" tabindex="-1">Improve Your Security <a class="header-anchor" href="#improve-your-security" aria-label="Permalink to “Improve Your Security”">​</a></h2><ul><li>Install modules from sources you recognize. Review a module&#39;s source and requested function before enabling it, remove module sources you no longer trust.</li><li>Keep integrity verification enabled. Do not approve an unknown module or disable verification unless you understand why it is necessary.</li><li>Avoid HTTP sources, especially on networks you do not control. Use HTTPS for backend and module source URL</li><li>Enable the Encryption module for sensitive vaults. Use a strong, unique password, keep it in Obsidian&#39;s secret storage, and configure it on every device before syncing encrypted files. Read the <a href="./../deep-dive/modules/encryption">encryption spec</a> before relying on it.</li><li>Protect your device and Obsidian vault with your operating system&#39;s updates, account protection, and disk encryption where available.</li><li>Give your backend account access only to the directory used by Sync Engine, and keep independent backups. Encryption cannot recover data deleted by a malicious backend.</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};